@push('scripts')<script>const limits=@json($periodLimits);const times=@json($periodTimeOptions);const day=document.getElementById('schedule-day'),period=document.getElementById('schedule-period'),label=document.getElementById('period-time');function fill(){const selected=period.value;period.innerHTML='';for(let i=1;i<=limits[day.value];i++){const t=times.find(x=>x.day==day.value&&x.number===i),o=document.createElement('option');o.value=i;o.textContent=`الحصة ${i}${t?' — '+t.start+' إلى '+t.end:''}`;period.append(o)}if(selected&&selected<=limits[day.value])period.value=selected;show()}function show(){const t=times.find(x=>x.day==day.value&&x.number==period.value);label.textContent=t?`الوقت المعتمد: ${t.start} — ${t.end}`:'وقت الحصة غير معرّف في الإعدادات'}day.addEventListener('change',fill);period.addEventListener('change',show);fill()</script>@endpush
